   265→- [ ] **Step 6: Implement matchUrl and buildUrl + RouteEntry type**
   266→
   267→Add to `route-compiler.ts`:
   268→
   269→```typescript
   270→import type { IconData } from "@/types/icon";  // adjust path as needed
   271→
   272→export interface RouteEntry<TParams extends Record<string, string> = Record<string, string>> {
   273→  pattern: string;
   274→  icon: IconData | ((params: TParams) => IconData);
   275→  title: string | ((params: TParams) => string);
   276→  titleKey?: string;
   277→  isContainer?: boolean;
   278→  queryParams?: string[];
   279→  dropdownCategory?: string;
   280→}
   281→
   282→export interface RouteMatch {
   283→  pattern: string;
   284→  params: Record<string, string>;
   285→  icon: IconData;
   286→  title: string;
   287→  entry: RouteEntry;
   288→}
   289→
   290→interface CompiledRoute extends CompiledPattern {
   291→  entry: RouteEntry;
   292→  queryParams: string[];
   293→}
   294→
   295→/** Compile all entries, sorted by specificity (more constant segments first, no-rest before rest) */
   296→export function compileRegistry(entries: RouteEntry[]): CompiledRoute[] {
   297→  const compiled = entries.map((entry) => ({
   298→    ...compilePattern(entry.pattern),
   299→    entry,
   300→    queryParams: entry.queryParams ?? [],
   301→  }));
   302→
   303→  // Sort: more constant segments first; tie-break: no rest before rest
   304→  compiled.sort((a, b) => {
   305→    if (b.constantSegmentCount !== a.constantSegmentCount) {
   306→      return b.constantSegmentCount - a.constantSegmentCount;
   307→    }
   308→    return (a.restParam ? 1 : 0) - (b.restParam ? 1 : 0);
   309→  });
   310→
   311→  return compiled;
   312→}
   313→
   314→export function matchUrl(url: string, entries: RouteEntry[]): RouteMatch | null {
   315→  const compiled = compileRegistry(entries);
   316→  return matchUrlCompiled(url, compiled);
   317→}
   318→
   319→export function matchUrlCompiled(url: string, compiled: CompiledRoute[]): RouteMatch | null {
   320→  const parsed = new URL(url, "http://localhost");
   321→  const pathname = parsed.pathname;
   322→
   323→  for (const route of compiled) {
   324→    const pathMatch = route.regex.exec(pathname);
   325→    if (!pathMatch) continue;
   326→
   327→    const params: Record<string, string> = {};
   328→    route.paramNames.forEach((name, i) => {
   329→      params[name] = decodeURIComponent(pathMatch[i + 1]);
   330→    });
   331→
   332→    for (const qp of route.queryParams) {
   333→      const value = parsed.searchParams.get(qp);
   334→      if (value) params[qp] = value;
   335→    }
   336→
   337→    return {
   338→      pattern: route.pattern,
   339→      params,
   340→      icon: resolveIcon(route.entry, params),
   341→      title: resolveTitle(route.entry, params),
   342→      entry: route.entry,
   343→    };
   344→  }
   345→  return null;
   346→}
   347→
   348→export function buildUrl(pattern: string, params: Record<string, string>, entries: RouteEntry[]): string {
   349→  const compiled = compileRegistry(entries);
   350→  return buildUrlCompiled(pattern, params, compiled);
   351→}
   352→
   353→export function buildUrlCompiled(pattern: string, params: Record<string, string>, compiled: CompiledRoute[]): string {
   354→  const route = compiled.find((r) => r.pattern === pattern);
   355→  if (!route) throw new Error(`Unknown pattern: ${pattern}`);
   356→
   357→  let path = route.build(params);
   358→
   359→  const queryEntries = route.queryParams
   360→    .filter((qp) => params[qp])
   361→    .map((qp) => [qp, params[qp]] as [string, string]);
   362→
   363→  if (queryEntries.length > 0) {
   364→    path += "?" + new URLSearchParams(queryEntries).toString();
   365→  }
   366→
   367→  return path;
   368→}
   369→
   370→function resolveIcon(entry: RouteEntry, params: Record<string, string>): IconData {
   371→  return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   372→}
   373→
   374→function resolveTitle(entry: RouteEntry, params: Record<string, string>): string {
   375→  return typeof entry.title === "function" ? entry.title(params) : entry.title;
   376→}
   377→```
