   452→  { pattern: "/subagent/:configId", icon: { type: "lucide", value: "bot" }, title: (p) => p.configId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
   453→  { pattern: "/prompt/:promptId", icon: { type: "lucide", value: "quote" }, title: (p) => p.promptId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
   454→  { pattern: "/command/:commandId", icon: { type: "lucide", value: "square-terminal" }, title: (p) => p.commandId, queryParams: ["workspace_path", "executor_type"], dropdownCategory: "detail" },
   455→];
