   457→// ─── Compiled Registry (singleton) ──────────────────────────────────────────
   458→
   459→const compiled: CompiledRoute[] = compileRegistry(ROUTE_ENTRIES);
   460→const compiledByPattern = new Map(compiled.map((r) => [r.pattern, r]));
   461→
   462→export const registry = {
   463→  match(url: string): RouteMatch | null {
   464→    return matchUrlCompiled(url, compiled);
   465→  },
   466→
   467→  build(pattern: string, params: Record<string, string> = {}): string {
   468→    return buildUrlCompiled(pattern, params, compiled);
   469→  },
   470→
   471→  getEntry(pattern: string): RouteEntry | undefined {
   472→    return compiledByPattern.get(pattern)?.entry;
   473→  },
   474→
   475→  hasEntry(pattern: string): boolean {
   476→    return compiledByPattern.has(pattern);
   477→  },
   478→
   479→  getRestParam(pattern: string): string | null {
   480→    return compiledByPattern.get(pattern)?.restParam ?? null;
   481→  },
   482→
   483→  getParamNames(pattern: string): string[] {
   484→    return compiledByPattern.get(pattern)?.paramNames ?? [];
   485→  },
   486→
   487→  getByCategory(category: string): RouteEntry[] {
   488→    return compiled.filter((r) => r.entry.dropdownCategory === category).map((r) => r.entry);
   489→  },
   490→
   491→  getIcon(pattern: string, params: Record<string, string> = {}): IconData | undefined {
   492→    const entry = compiledByPattern.get(pattern)?.entry;
   493→    if (!entry) return undefined;
   494→    return typeof entry.icon === "function" ? entry.icon(params) : entry.icon;
   495→  },
   496→
   497→  normalizeUrl(url: string): string {
   498→    const match = this.match(url);
   499→    if (!match) {
   500→      const { pathname } = new URL(url, "http://localhost");
   501→      return pathname;
   502→    }
   503→    return this.build(match.pattern, match.params);
   504→  },
   505→};
   506→
   507→// ─── Helpers ────────────────────────────────────────────────────────────────
   508→
   509→export function humanize(slug: string): string {
   510→  return slug.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
   511→}
